import { Component, For, onCleanup, onMount, ParentComponent, Show, splitProps, useContext } from "solid-js";
import { useAudio } from "#core/ui-next/services/audio-support.js";
import { Activatable } from "#core/ui-next/components/activatable.jsx";
import { AudioContextProvider } from "#core/ui-next/components/audio-context-provider.jsx";
import { CardFrame } from "#core/ui-next/components/card-frame.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { PortraitIcon } from "#core/ui-next/components/portrait-icon.jsx";
import { ProgressBar } from "#core/ui-next/components/progress-bar.jsx";
import { ScrollArea } from "#core/ui-next/components/scroll-area.jsx";
import { HSlot, VSlot } from "#core/ui-next/components/slot.jsx";
import { Tooltip, TooltipHorizontalPosition, TooltipVerticalPosition } from "#core/ui-next/components/tooltip.jsx";
import { HotkeyContext } from "#core/ui-next/services/hotkey.js";
import { LayoutModel, useIsSmallScreen } from "#core/ui-next/utilities/layout-utilities.js";

import {
	PointGoalProps,
	SummaryVictoryProps,
	useVictoriesScreenContext,
	VictoryDominantPlayer,
	VictoryTooltipProps,
} from "#base/ui-next/screens/victories/victories-screen-model.js";
import { VictoryRulesTooltip } from "#base/ui-next/screens/victories/victory-tab-base.jsx";

const lockedTooltip: VictoryTooltipProps = {
	descTitle: "LOC_VICTORY_LOCKED_TITLE",
	description: "LOC_VICTORY_LOCKED_BODY",
	currentVictoryName: "",
	currentVictoryMult: -1,
	currentVictoryPercent: -1,
	nextVictoryName: "",
	nextVictoryMult: -1,
	nextVictoryPercent: -1,
};

const audio = useAudio("VictoryScreen/TabListItem")

export const VictoriesSummary: Component = () => {
	const model = useVictoriesScreenContext();
	const isSmallScreen = useIsSmallScreen();
	const hotkeyContext = useContext(HotkeyContext);

	onMount(() => {
		if (model.data.panels.some((p) => p.visible)) {
			hotkeyContext.registerNavtray("accept", "LOC_VICTORY_NAV_HELP_SUMMARY_ACCEPT");
			hotkeyContext.registerNavtray("shell-action-3", "LOC_VICTORY_NAV_HELP_RULES");
		}
		model.tabNavStartup(hotkeyContext);
		audio("tab-nav-summary")
	});

	onCleanup(() => {
		if (model.data.panels.some((p) => p.visible)) {
			hotkeyContext.unregisterNavtray("accept");
			hotkeyContext.unregisterNavtray("shell-action-3");
		}
		model.tabNavShutdown(hotkeyContext);
	});

	return (
		<div class="flex-1">
			<Show when={!isSmallScreen()}>
				<div class="absolute left-12 -top-6 victories-header">
					<VSlot class="font-body text-body text-xs self-center">
						<Show
							when={
								Game.AgeProgressManager.isExtendedGame ||
								Game.AgeProgressManager.getMaxAgeProgressionPoints() <= 0
							}
							fallback={<L10n.Compose text="LOC_VICTORY_SUMMARY_HEADER" />}
						>
							<L10n.Compose text="LOC_VICTORY_OMT_SUMMARY_HEADER" />
						</Show>
					</VSlot>
				</div>
			</Show>
			<ScrollArea
				class="h-full relative"
				useProxy={true}
			>
				<Show
					when={model.data.panels.some((p) => p.visible)}
					fallback={
						<div class="self-center font-body text-base text-white mt-12">
							<L10n.Compose
								text={
									Game.VictoryManager.isScoreVictoryEnabled()
										? "LOC_VICTORY_SUMMARY_ONLY_SCORE_ENABLED"
										: "LOC_VICTORY_SUMMARY_ALL_DISABLED"
								}
							/>
						</div>
					}
				>
					<div class="w-full h-full self-center victories-summary-main flex flex-col shrink">
						<VSlot class="relative self-center mx-1 victories-summary-focus flex-1">
							<HSlot
								class="victories-summary-container w-full flex-1"
								lockNavigation={true}
								autoFocus={!model.tooltipToggle}
							>
								<For each={model.data.panels}>{(card) => <Show when={card.visible}><SummaryVictoryCard {...card} /></Show>}</For>
							</HSlot>
						</VSlot>
					</div>
				</Show>
			</ScrollArea>
		</div>
	);
};

const SummaryVictoryCard: Component<SummaryVictoryProps> = (props) => {
	const [panelProps] = splitProps(props, ["rules", "titleText", "titleColor", "hasFocus"]);
	const isOneMoreTurn =
		Game.AgeProgressManager.isExtendedGame || Game.AgeProgressManager.getMaxAgeProgressionPoints() <= 0;
	const model = useVictoriesScreenContext();

	function onActivate() {
		model.data.defaultTab = model.data.currentTab();
		model.data.defaultTab = props.tabId;
		useAudio("VictoryScreen/SummaryCard")("navigate-tab");
	}

	function onFocus() {
		const panel = model.data.panels.find((p) => p.tabId === props.tabId);
		if (panel) {
			panel.hasFocus = true;
		}
	}

	function onBlur() {
		const panel = model.data.panels.find((p) => p.tabId === props.tabId);
		if (panel) {
			panel.hasFocus = false;
		}
	}

	const titleFontSizeClass = LayoutModel.get().screenWidthDownScaled() < 1784 ? "text-lg" : "text-2xl";

	return (
		<AudioContextProvider segment="SummaryCard">
			<VictoryTooltip
				class="victories-tooltip"
				{...(props.goals.pointGoal != -1 ? props.goals.tooltipInfo : lockedTooltip)}
			>
				<Activatable
					class={`victories-summary-box pointer-events-auto duration-150 ease-out justify-between font-title text-center text-white text-2xl relative flex flex-col ${props.divider === true ? "victories-summary-divider" : ""} `}
					style={{
						"transition-property": "opacity",
					}}
					data-name="SummaryVictoryCard"
					name={Locale.compose(props.titleText)}
					tabIndex={-1}
					onActivate={onActivate}
					onFocus={onFocus}
					onBlur={onBlur}
				>
					<div
						class={`victories-summary-bg pointer-events-auto absolute inset-0 bg-no-repeat bg-cover opacity-40 ${props.summaryBg}`}
					/>
					<div>
						<VSlot class="w-full">
							<div class={`uppercase font-bold ${titleFontSizeClass} mt-6 ${props.titleColor}`}>
								<div role="heading">
									<L10n.Compose text={props.titleText} />
								</div>
							</div>
							<div class="victories-summary-header-lines promotion-header__lines self-center bg-cover bg-no-repeat pointer-events-none flex-auto" />
							<div class={`self-center size-8 -mt-6 ${props.victoryLogo}`} />

							<div class="font-body text-2xs self-center mt-4 mx-6 h-16 opacity-60">
								<div role="heading">
									<L10n.Compose text={props.description} />
								</div>
							</div>

							<PointGoalPanel
								{...props.goals}
								{...panelProps}
							/>
						</VSlot>

						<Show when={props.dominantPlayer.length == 1 && !isOneMoreTurn}>
							<div class="h-16 w-8" />
						</Show>

						<Show when={!isOneMoreTurn}>
							<For each={props.dominantPlayer}>
								{(player) => (
									<div class="w-full px-4">
										<DominanceCountdownCard {...player} />
									</div>
								)}
							</For>
						</Show>
					</div>
				</Activatable>
			</VictoryTooltip>
		</AudioContextProvider>
	);
};

const DominanceCountdownCard: Component<VictoryDominantPlayer> = (props) => {
	return (
		<div
			class={`relative img-base-ticket-bg-container self-center w-full px-4 min-h-32 mb-5 ${props.id == -1 ? "opacity-0" : ""}`}
		>
			<div
				class="absolute top-2 left-2 rotate-180 size-4 bg-contain"
				style={{ "background-image": "url(blp:mp_player_detail)" }}
			/>
			<div
				class="absolute top-2 right-2 -rotate-90 size-4 bg-contain"
				style={{ "background-image": "url(blp:mp_player_detail)" }}
			/>
			<div
				class="absolute bottom-2 left-2 rotate-90 size-4 bg-contain"
				style={{ "background-image": "url(blp:mp_player_detail)" }}
			/>
			<div
				class="absolute bottom-2 right-2 size-4 bg-contain"
				style={{ "background-image": "url(blp:mp_player_detail)" }}
			/>
			<div class="absolute inset-0">
				<VSlot class="w-full items-center">
					<div
						class="relative h-7 w-full max-w-128 bg-contain bg-no-repeat pointer-events-none"
						style={{ "background-image": "url(blp:cPromo_header)" }}
					/>
					<div class="size-10 -ml-1 -mt-12 mb-1 victories-trophy" />
					<div
						class="font-title text-2xs text-secondary uppercase victories-countdown-title"
						role="heading"
					>
						<L10n.Compose text="LOC_VICTORY_PROGRESS_COUNTDOWN" />
					</div>
					<div
						class="font-title text-2xs text-body uppercase"
						role="heading"
					>
						<L10n.Compose
							text="LOC_VICTORY_PROGRESS_TURNS_REMAINING"
							args={[props.turns]}
						/>
					</div>
					<div
						class="victories-progress-bar relative mt-1"
						role="heading"
					>
						<ProgressBar
							class="relative w-full "
							progressPercent={props.percent}
						/>
						<div
							class="absolute -top-2 bottom-0 -ml-4 mt-1"
							style={{ left: props.percent.toString() + "%" }}
							role="heading"
						>
							<Tooltip.Text text={Locale.stylize(props.name)}>
								<PortraitIcon
									playerId={props.id}
									size={10}
								/>
							</Tooltip.Text>
						</div>
					</div>
				</VSlot>
			</div>
		</div>
	);
};

const PointGoalPanel: Component<PointGoalProps> = (props) => {
	return (
		<div
			class={`${props.class}`}
			data-name="Point-Goal-Panel"
		>
			<VSlot
				class="px-4 w-full"
				disableFocus={true}
			>
				<div>
					<HSlot class="relative w-full">
						<HSlot class="mt-1 ml-3 h-7">
							<VictoryRulesTooltip
								size={6}
								initialHPosition={TooltipHorizontalPosition.AUTO}
								initialVPosition={TooltipVerticalPosition.AUTO}
								class="self-center mr-2 opacity-100"
								tooltipText={props.rules}
								titleText={props.titleText}
								titleClass={props.titleColor}
								disableFocus={!props.hasFocus}
							/>
						</HSlot>
						<HSlot class="self-center flex-1 justify-between mx-2">
							<div
								class="font-title-sm opacity-80 uppercase ml-1"
								role="heading"
							>
								<L10n.Compose text="LOC_VICTORY_PROGRESS_POINT_GOAL" />
							</div>
							<Show
								when={props.pointGoal != -1}
								fallback={
									<div
										class="font-body text-base"
										role="heading"
									>
										<Tooltip.Text text={Locale.stylize("LOC_VICTORY_NOVICTORIES_TOOLTIP")}>
											-
										</Tooltip.Text>
									</div>
								}
							>
								<div
									class="font-body-sm opacity-80"
									role="heading"
								>
									{Locale.toNumber(props.pointGoal)}
								</div>
							</Show>
						</HSlot>
					</HSlot>
					<div class="victories-point-goal-line w-full justify-center mx-4" />
				</div>
				<For each={props.leaderBoard}>
					{(leader, index) => (
						<div>
							<Show when={index() == 3}>
								<HSlot class="victories-point-goal-line w-full justify-center mx-4">
									<div class="img-popup-middle-decor size-16" />
								</HSlot>
							</Show>
							<HSlot class="relative w-full">
								<Show when={leader.winner}>
									<div
										class="absolute top-0 bottom-1 left-0 right-0 -ml-6 bg-no-repeat bg-cover"
										style={{ "background-image": "url(blp:victories_gold_banner)" }}
									/>
								</Show>
								<HSlot class="justify-between h-14 my-1 w-full">
									<HSlot class="w-full">
										<div class="mr-2 self-center">
											<PortraitIcon
												playerId={leader.hasMet ? leader.id : PlayerIds.NO_PLAYER}
												size={12}
											/>
										</div>
										<HSlot class="flex-1 justify-between">
											<VSlot class="self-center">
												<HSlot
													class={`victories-name-field font-body text-2xs self-center -ml-2 flex-wrap ${leader.winner || leader.id == GameContext.localPlayerID ? "" : " opacity-60"}`}
													role="heading"
												>
													<div class="flex flex-row">{leader.place}. </div>
													<L10n.Compose
														text={
															leader.id == GameContext.localPlayerID
																? "LOC_VICTORY_LEADER_NAME_YOU"
																: "LOC_VICTORY_LEADER_NAME"
														}
														args={[
															leader.hasMet ? leader.name : "LOC_UI_UNMET_PLAYER_NAME",
														]}
													/>
												</HSlot>
												<Show when={leader.dominant == true || leader.turnsProgress > 0}>
													<HSlot
														class="font-body text-xs self-start ml-2"
														role="heading"
													>
														<div
															class={`flex flex-col self-center ${leader.id == GameContext.localPlayerID ? "" : " opacity-60"}`}
														>
															<div class="flex flex-row">
																{leader.turnsProgress}/{leader.turnsTotal}
															</div>
														</div>
														<div class="victories-trophy size-6" />
													</HSlot>
												</Show>
											</VSlot>
											<div
												class={`font-body text-2xs self-center mr-2 ${leader.id == GameContext.localPlayerID ? "" : "opacity-60"}`}
												role="heading"
											>
												{Locale.toNumber(leader.points)}
											</div>
										</HSlot>
									</HSlot>
								</HSlot>
								<Show when={leader.winner}>
									<div
										class="absolute inset-0 -top-1 bg-no-repeat bg-cover"
										style={{ "background-image": "url(blp:victories_gold_lines)" }}
									/>
								</Show>
							</HSlot>
							<div class="victories-point-goal-line w-full justify-center mx-4" />
						</div>
					)}
				</For>
			</VSlot>
		</div>
	);
};

//region TOOLTIP
export const VictoryTooltip: ParentComponent<VictoryTooltipProps> = (props) => {
	const [local, _other] = splitProps(props, ["children", "class"]);

	return (
		<Tooltip
			initialHPosition={TooltipHorizontalPosition.RIGHT}
			initialVPosition={TooltipVerticalPosition.CENTER}
		>
			<Tooltip.Trigger>{local.children}</Tooltip.Trigger>
			<Tooltip.Content class={local.class}>
				<Tooltip.Frame>
					<div class="items-center">
						<div class="font-title text-xs text-secondary uppercase self-center mb-4">
							<L10n.Compose text="LOC_VICTORY_TOOLTIP_TITLE" />
						</div>
						<CardFrame class="mb-4">
							<div class="font-title text-xs text-secondary uppercase self-center mt-2 mb-2">
								<L10n.Compose text={props.descTitle} />
							</div>
							<div class="font-body text-xs text-white self-center justify-center mb-2 w-128">
								<L10n.Compose text={props.description} />
							</div>
						</CardFrame>
						<Show when={props.currentVictoryPercent != -1}>
							<CardFrame class="mb-4">
								<div class="font-title text-xs text-secondary uppercase self-center mt-2 mb-2">
									<L10n.Compose text={props.currentVictoryName} />
								</div>
								<div class="font-body text-xs text-white self-center justify-center mb-2 w-128">
									<L10n.Compose
										text="LOC_VICTORY_TOOLTIP_REQUIREMENTS"
										args={[props.currentVictoryMult, props.currentVictoryPercent]}
									/>
								</div>
							</CardFrame>
						</Show>
						<Show when={props.nextVictoryPercent != -1}>
							<CardFrame class="mb-4">
								<div class="font-title text-xs text-secondary uppercase self-center mt-2 mb-2">
									<L10n.Compose
										text="LOC_VICTORY_TOOLTIP_NEXT"
										args={[props.nextVictoryName]}
									/>
								</div>
								<div class="font-body text-xs text-white self-center justify-center mb-2 w-128">
									<L10n.Compose
										text="LOC_VICTORY_TOOLTIP_REQUIREMENTS"
										args={[props.nextVictoryMult, props.nextVictoryPercent]}
									/>
								</div>
							</CardFrame>
						</Show>
					</div>
				</Tooltip.Frame>
			</Tooltip.Content>
		</Tooltip>
	);
};
//#endregion
